type Bit is Data:
  BitZero{}
  BitOne{}
def select(left: Bit, right: Bit) -> Bit:
  left
def main() -> Bit:
  {select!(BitOne{}) : Bit -> Bit}(BitZero{})

type Bit is Data:
  BitZero{}
  BitOne{}
type Count is Data:
  CZero{}
  CSucc{pred: Count}
def select(left: Bit, right: Bit) -> Bit:
  left
def main() -> Bit:
  {select!(BitOne{}) : Bit -> Count}(BitZero{})
